arguments.command:
cat > /app/w/solve.py <<'EOF'
import numpy as np,json,sys
from functools import lru_cache
M={k:np.array(v) for k,v in json.load(open('/app/w/M.json')).items()}
CH=['bureau','income','bank']
PD=np.array([.02,.05,.12,.3,.6,.9]);A=(1-PD)*1000-PD*16000
def solve(prior,hist):
    prior=np.array(prior,float)
    @lru_cache(None)
    def V(state):  # state: sorted tuple of (ci,b)
        w=prior.copy()
        for ci,b in state: w=w*M[CH[ci]][:,b]
        Z=w.sum(); p=w/Z
        stop=max(0,p@A)
        best=(stop,'approve' if p@A>0 else 'decline')
        if len(state)<8:
            for ci in range(3):
                pb=p@M[CH[ci]]
                v=-20+sum(pb[b]*V(tuple(sorted(state+((ci,b),))))[0] for b in range(6) if pb[b]>1e-12)
                if v>best[0]+1e-9: best=(v,CH[ci])
        return best
    st=tuple(sorted((CH.index(c),b) for c,b in hist))
    return V(st), max(0,prior@A)
if __name__=='__main__':
    prior=json.loads(sys.argv[1]); hist=json.loads(sys.argv[2]) if len(sys.argv)>2 else []
    print(solve(prior,hist))
EOF
